pub struct Counter {
    pub n: u32,
}

impl Counter {
    pub fn new() -> Self {
        Counter { n: 0 }
    }

    pub fn bump(&self) {
        self.n += 1;
    }
}

pub fn run() -> u32 {
    let mut c = Counter::new();
    c.bump();
    c.bump();
    c.n
}

