pub struct Rect {
    pub w: u32,
    pub h: u32,
}

impl Rect {
    pub fn area(self) -> u32 {
        self.w * self.h
    }

    pub fn scaled(self, k: u32) -> Rect {
        Rect { w: self.w * k, h: self.h * k }
    }
}

pub fn run() -> (u32, u32) {
    let r = Rect { w: 3, h: 4 };
    (r.area(), r.scaled(2).area())
}

