pub struct Cents(pub i64);
pub struct Dollars(pub i64);

impl Dollars {
    pub fn to_cents(self) -> Cents {
        Cents(self.0 * 100)
    }
}

pub fn add(a: Cents, b: Cents) -> Cents {
    Cents(a.0 + b.0)
}

pub fn run() -> i64 {
    let price = Cents(250);
    let discount = Dollars(2);
    add(price, discount.to_cents()).0
}

